from pathlib import Path
import base64,hashlib,io,json,os,subprocess,sys,tarfile,time
PAYLOAD = ''
STAGE=Path('/workspace/p26-cell05-runtime-recovery-20261127-v2')
TOOL=STAGE/'tools/p26/cell05-runtime-recovery-20261127'
def need(value,message):
 if not value: raise ValueError(message)
def pin(path):
 path=Path(path);body=path.read_bytes();return {'path':str(path),'bytes':len(body),'sha256':hashlib.sha256(body).hexdigest()}
def write_new(path,body):
 need(path.resolve()==path and not path.is_symlink(),'Noncanonical new output')
 with path.open('xb') as f:f.write(body)
def encoded(value):return (json.dumps(value,indent=2)+'\n').encode()
raw=base64.b64decode(PAYLOAD,validate=True)
need(len(raw)==29252 and hashlib.sha256(raw).hexdigest()=='051a67f0196a5c7f2b62eaef1506331b4d53730120c8825e515db9a9ddb8bdb4','Deployment bundle changed')
files={}
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:xz') as t:
 for m in t:
  need(m.isfile() and not m.issym() and not m.islnk() and Path(m.name).name==m.name and m.name not in files,'Unsafe deployment member')
  files[m.name]=t.extractfile(m).read()
need(len(files)==10,'Wrong deployment count')
mb=files['WORKFLOW_MANIFEST.json'];need(len(mb)==1493 and hashlib.sha256(mb).hexdigest()=='e3f9588b43b5d3bb08a24f6938c1e6dde2e9968a719f06f28bbcd8166e822d3e','Wrong reviewed workflow')
manifest=json.loads(mb)
need(set(files)=={'WORKFLOW_MANIFEST.json'}|{r['relative_path'] for r in manifest['files']},'Deployment inventory differs')
for r in manifest['files']:
 body=files[r['relative_path']];need(len(body)==r['bytes'] and hashlib.sha256(body).hexdigest()==r['sha256'],'Deployment payload changed')
need(STAGE.resolve()==STAGE and not STAGE.exists() and not STAGE.is_symlink(),'Recovery stage already exists; preserve it')
STAGE.mkdir();TOOL.mkdir(parents=True)
for name,body in files.items():write_new(TOOL/name,body)
write_new(STAGE/'DEPLOYMENT_BUNDLE.tar.xz',raw)
stdout=STAGE/'CAPTURE_OUTPUT.json';stderr=STAGE/'CAPTURE.stderr'
argv=[sys.executable,'-I','-S','-B',str(TOOL/'recovery.py'),'capture']
print(json.dumps({'kind':'capture_started','argv':argv,'workflow_manifest':pin(TOOL/'WORKFLOW_MANIFEST.json'),'Lean_commands':0}),flush=True)
start=time.monotonic()
with stdout.open('xb') as out,stderr.open('xb') as err:
 result=subprocess.run(argv,stdout=out,stderr=err,check=False,timeout=3300)
outcome={'schema':'p26_explicit_recovery_capture_process_v1','argv':argv,'exit_code':result.returncode,'elapsed_seconds':time.monotonic()-start,'stdout':pin(stdout),'stderr':pin(stderr),'workflow_manifest':pin(TOOL/'WORKFLOW_MANIFEST.json'),'old_Lean_commands':0}
write_new(STAGE/'CAPTURE_PROCESS.json',encoded(outcome))
print(json.dumps({'kind':'capture_process_finished',**outcome}),flush=True)
if result.returncode:
 print(stderr.read_text(errors='replace')[-24000:],flush=True);sys.exit(result.returncode)
view=json.loads(stdout.read_bytes())
need(view['status']=='PASS_EXPLICIT_RUNTIME_RECOVERY' and len(view['dependencies'])==125 and view['original_live_guard_validator_passed'] is False,'Unexpected capture output')
print(json.dumps({'kind':'capture_certified','certificate':view['certificate'],'history':view['history'],'current_runtime_guard':view['current_runtime_guard'],'suppliers':len(view['dependencies']),'prefix8_steps':view['prefix8']['accepted_steps'],'old_Lean_commands':0,'P2_6_complete':False}),flush=True)
entries=[('protocol/'+name,TOOL/name) for name in sorted(files)]
entries += [('capture/'+name,STAGE/name) for name in ('CURRENT_RUNTIME_GUARD.json','HISTORICAL_VALIDATION.json','CERTIFICATE.json','CAPTURE_OUTPUT.json','CAPTURE.stderr','CAPTURE_PROCESS.json')]
entries += [('original/ORIGINAL_RUNTIME_GUARD.json',Path(view['original_runtime_guard']['path'])),('original/ORIGINAL_RUNTIME_SNAPSHOT.json',Path(view['original_snapshot']['path']))]
export={'schema':'p26_explicit_runtime_recovery_export_v1','certificate':view['certificate'],'members':[{'member':name,**pin(path)} for name,path in sorted(entries)],'old_Lean_commands':0,'P2_6_complete':False}
export_path=STAGE/'RECOVERY_EXPORT_MANIFEST.json';write_new(export_path,encoded(export))
archive=STAGE/'RECOVERY_EXPORT.tar.xz'
need(not archive.exists(),'Existing recovery export')
with tarfile.open(archive,mode='x:xz',preset=6,format=tarfile.PAX_FORMAT) as t:
 for name,path in sorted(entries+[('EXPORT_MANIFEST.json',export_path)]):
  b=path.read_bytes();i=tarfile.TarInfo(name);i.size=len(b);i.mode=0o644;i.mtime=0;i.uid=i.gid=0;i.uname=i.gname='';t.addfile(i,io.BytesIO(b))
for row in export['members']:need(pin(row['path'])=={k:row[k] for k in ('path','bytes','sha256')},'Evidence changed during export')
print(json.dumps({'kind':'capture_export_ready','archive':pin(archive),'manifest':pin(export_path),'members':len(entries)+1,'Lean_commands':0}),flush=True)
